);

CREATE TABLE `Vocals` (
  `SongId` NUMBER REFERENCES `Songs`(`SongId`),
  `Bandmate` NUMBER REFERENCES `Band`(`Id`),
  `Type` TEXT,
  PRIMARY KEY (`SongId`)
);

